function formatWorkshop(workshop) {
  if (workshop === null || typeof workshop !== 'object' || Array.isArray(workshop)) {
    throw new TypeError('workshop must be an object');
  }
  const { title, seats, topics } = workshop;
  if (typeof title !== 'string' || title.trim() === '') {
    throw new TypeError('title must be a non-empty string');
  }
  if (!Number.isInteger(seats)) {
    throw new TypeError('seats must be an integer');
  }
  if (seats < 0 || seats > 10000) {
    throw new RangeError('seats is out of range');
  }
  if (!Array.isArray(topics)) {
    throw new TypeError('topics must be an array');
  }
  const normalizedTopics = topics.map((topic) => {
    if (typeof topic !== 'string' || topic.trim() === '') {
      throw new TypeError('each topic must be a non-empty string');
    }
    return topic.trim();
  });
  return {
    heading: `${title.trim()} (${seats + 1} seats)`,
    topics: normalizedTopics
  };
}

module.exports = { formatWorkshop };

