'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['formatWorkshop']);
const { formatWorkshop } = api;
assert.strictEqual(typeof formatWorkshop, 'function');

const input = { title: '  JS Workshop  ', seats: 25, topics: [' basics ', 'async', ' basics '], ignored: true };
const originalTopics = input.topics.slice();
const result = formatWorkshop(input);
assert.deepStrictEqual(result, { heading: 'JS Workshop (25 seats)', topics: ['basics', 'async', 'basics'] });
assert.deepStrictEqual(input.topics, originalTopics);
assert.strictEqual(input.title, '  JS Workshop  ');
assert.notStrictEqual(result.topics, input.topics);

assert.deepStrictEqual(formatWorkshop({ title: 'A', seats: 0, topics: [] }), { heading: 'A (0 seats)', topics: [] });
assert.deepStrictEqual(formatWorkshop({ title: '\tFull\n', seats: 10000, topics: ['\tx\n'] }), { heading: 'Full (10000 seats)', topics: ['x'] });

for (const value of [null, undefined, [], 'x', 1]) {
  assert.throws(() => formatWorkshop(value), TypeError);
}
for (const title of ['', '   ', '\n\t', 3, null]) {
  assert.throws(() => formatWorkshop({ title, seats: 1, topics: [] }), TypeError);
}
for (const seats of [-1, 10001]) {
  assert.throws(() => formatWorkshop({ title: 'A', seats, topics: [] }), RangeError);
}
for (const seats of [1.5, NaN, Infinity, '1', null]) {
  assert.throws(() => formatWorkshop({ title: 'A', seats, topics: [] }), TypeError);
}
for (const topics of [null, {}, 'x', [1], [' '], ['ok', '']]) {
  assert.throws(() => formatWorkshop({ title: 'A', seats: 1, topics }), TypeError);
}

const frozenTopics = Object.freeze([' a ', 'b']);
const frozen = Object.freeze({ title: ' T ', seats: 2, topics: frozenTopics });
assert.deepStrictEqual(formatWorkshop(frozen), { heading: 'T (2 seats)', topics: ['a', 'b'] });

